ALTER TABLE issues_issues ADD COLUMN priority_level TEXT NOT NULL DEFAULT 'medium';
ALTER TABLE issues_issues ADD COLUMN status TEXT NOT NULL DEFAULT 'todo';
ALTER TABLE issues_issues ADD COLUMN status_id TEXT NOT NULL DEFAULT 'status_todo';
ALTER TABLE issues_issues ADD COLUMN type_id TEXT;
ALTER TABLE issues_issues ADD COLUMN parent_id TEXT;
ALTER TABLE issues_issues ADD COLUMN labels TEXT NOT NULL DEFAULT '[]';
ALTER TABLE issues_issues ADD COLUMN created_by_id TEXT NOT NULL DEFAULT '';
ALTER TABLE issues_issues ADD COLUMN created_by_kind TEXT NOT NULL DEFAULT 'human';
ALTER TABLE issues_issues ADD COLUMN created_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE issues_issues ADD COLUMN updated_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE issues_issues ADD COLUMN completed_at INTEGER;
ALTER TABLE issues_comments ADD COLUMN updated_at INTEGER NOT NULL DEFAULT 0;
INSERT OR IGNORE INTO issues_purge_bypass(workspace_id,project_id) SELECT workspace_id,project_id FROM issues_frozen_scopes;
UPDATE issues_issues SET priority_level=priority,status=state,status_id='status_'||state,created_at=COALESCE((SELECT occurred_at FROM issues_history h WHERE h.workspace_id=issues_issues.workspace_id AND h.issue_id=issues_issues.id ORDER BY occurred_at,version LIMIT 1),0),created_by_id=COALESCE((SELECT actor_id FROM issues_history h WHERE h.workspace_id=issues_issues.workspace_id AND h.issue_id=issues_issues.id ORDER BY occurred_at,version LIMIT 1),''),created_by_kind=COALESCE((SELECT actor_kind FROM issues_history h WHERE h.workspace_id=issues_issues.workspace_id AND h.issue_id=issues_issues.id ORDER BY occurred_at,version LIMIT 1),'human'),updated_at=COALESCE((SELECT MAX(occurred_at) FROM issues_history h WHERE h.workspace_id=issues_issues.workspace_id AND h.issue_id=issues_issues.id),0),completed_at=CASE WHEN state='done' THEN COALESCE((SELECT MAX(occurred_at) FROM issues_history h WHERE h.workspace_id=issues_issues.workspace_id AND h.issue_id=issues_issues.id),0) ELSE NULL END;
UPDATE issues_comments SET updated_at=created_at;
DELETE FROM issues_purge_bypass WHERE EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=issues_purge_bypass.workspace_id AND f.project_id=issues_purge_bypass.project_id);
CREATE TRIGGER issues_check_issues_insert BEFORE INSERT ON issues_issues WHEN NEW.priority_level NOT IN ('none','low','medium','high','urgent') OR NEW.created_by_kind NOT IN ('human','machine') BEGIN SELECT RAISE(ABORT,'invalid issue field'); END;
CREATE TRIGGER issues_check_issues_update BEFORE UPDATE ON issues_issues WHEN NEW.priority_level NOT IN ('none','low','medium','high','urgent') OR NEW.created_by_kind NOT IN ('human','machine') BEGIN SELECT RAISE(ABORT,'invalid issue field'); END;
CREATE INDEX issues_created_order ON issues_issues(workspace_id,created_at,id);
CREATE INDEX issues_parent ON issues_issues(workspace_id,parent_id);
CREATE INDEX issues_status ON issues_issues(workspace_id,status_id);
